import{_ as i,o as a,c as n,ag as e}from"./chunks/framework.DEqXEGcv.js";const c=JSON.parse('{"title":"Children Declaration","description":"","frontmatter":{},"headers":[],"relativePath":"composition/children-declaration.md","filePath":"composition/children-declaration.md"}'),t={name:"composition/children-declaration.md"};function l(h,s,p,d,k,r){return a(),n("div",null,[...s[0]||(s[0]=[e(`<h1 id="children-declaration" tabindex="-1">Children Declaration <a class="header-anchor" href="#children-declaration" aria-label="Permalink to &quot;Children Declaration&quot;">​</a></h1><p>The <code>CHILDREN</code> block in a parent machine and the <code>PARENT</code> declaration in a child machine together establish a composition relationship.</p><h2 id="children-block" tabindex="-1">CHILDREN Block <a class="header-anchor" href="#children-block" aria-label="Permalink to &quot;CHILDREN Block&quot;">​</a></h2><p>Declared inside <code>DEFINE MACHINE</code>, the <code>CHILDREN</code> block names each child slot, its cardinality, and optional constraints:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Order (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    items    : LIST(LineItem)      </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    shipment : OPTIONAL(Shipment)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><h3 id="cardinality-types" tabindex="-1">Cardinality Types <a class="header-anchor" href="#cardinality-types" aria-label="Permalink to &quot;Cardinality Types&quot;">​</a></h3><table tabindex="0"><thead><tr><th>Type</th><th>Meaning</th><th>Example</th></tr></thead><tbody><tr><td><code>LIST(Machine)</code></td><td>Zero or more children of that type</td><td><code>items : LIST(LineItem)</code></td></tr><tr><td><code>OPTIONAL(Machine)</code></td><td>Zero or one child of that type</td><td><code>shipment : OPTIONAL(Shipment)</code></td></tr></tbody></table><h3 id="constraints" tabindex="-1">Constraints <a class="header-anchor" href="#constraints" aria-label="Permalink to &quot;Constraints&quot;">​</a></h3><p>Constraints follow the <code>-&gt;</code> arrow, just like data field constraints:</p><table tabindex="0"><thead><tr><th>Constraint</th><th>Applies to</th><th>Meaning</th></tr></thead><tbody><tr><td><code>MIN(n)</code></td><td>LIST</td><td>Minimum number of children required</td></tr><tr><td><code>MAX(n)</code></td><td>LIST</td><td>Maximum number of children allowed</td></tr></tbody></table><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  items    : LIST(LineItem)    </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">MAX</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">100</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  shipment : OPTIONAL(Shipment)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p><code>OPTIONAL</code> implicitly means MIN(0), MAX(1) -- the engine enforces that at most one child of that type exists.</p><h2 id="parent-declaration" tabindex="-1">PARENT Declaration <a class="header-anchor" href="#parent-declaration" aria-label="Permalink to &quot;PARENT Declaration&quot;">​</a></h2><p>Every child machine must declare its parent type with <code>PARENT</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE LineItem (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PARENT : Order</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  DATA</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    product  : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">TEXT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">        -&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> REQUIRED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    quantity : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">INT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">         -&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">), </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">REQUIRED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    price    : </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">MONEY</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(USD)  </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> REQUIRED</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  STATES { pending, confirmed, backordered, cancelled }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  INITIAL </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">STATE</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> pending</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TERMINAL STATES { confirmed, cancelled }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  TRANSITIONS {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pending </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> confirmed { GUARD : quantity </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> 0</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    pending </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> backordered {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    backordered </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> confirmed {}</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    ANY </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> cancelled { </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">EXCEPT</span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;"> FROM</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> { confirmed } }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><p>The <code>PARENT</code> line must appear before the <code>DATA</code> block. The named machine must exist in the catalog and must declare a matching <code>CHILDREN</code> entry.</p><h2 id="the-parent-keyword-in-expressions" tabindex="-1">The PARENT Keyword in Expressions <a class="header-anchor" href="#the-parent-keyword-in-expressions" aria-label="Permalink to &quot;The PARENT Keyword in Expressions&quot;">​</a></h2><p>Inside a child machine&#39;s transitions, <code>PARENT</code> refers to the parent instance. You can access parent data fields:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">pending </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> backordered {</span></span>
<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">  ACTION</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> : NOTIFY(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">PARENT</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">.</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">customer</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;item.backordered&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">}</span></span></code></pre></div><p>Here, <code>PARENT.customer</code> resolves to the <code>customer</code> field on the parent Order instance.</p><h2 id="internal-representation" tabindex="-1">Internal Representation <a class="header-anchor" href="#internal-representation" aria-label="Permalink to &quot;Internal Representation&quot;">​</a></h2><p>Each child instance carries two internal fields:</p><table tabindex="0"><thead><tr><th>Field</th><th>Description</th></tr></thead><tbody><tr><td><code>parent_id</code></td><td>The ULID of the parent instance</td></tr><tr><td><code>parent_machine</code></td><td>The machine type of the parent (e.g., <code>&quot;Order&quot;</code>)</td></tr></tbody></table><p>These are set automatically when a child is spawned and cannot be changed. The engine maintains a parent index for fast lookups -- given a parent ID, it can efficiently find all children.</p><h2 id="defining-both-sides" tabindex="-1">Defining Both Sides <a class="header-anchor" href="#defining-both-sides" aria-label="Permalink to &quot;Defining Both Sides&quot;">​</a></h2><p>A valid composition requires both sides to be defined. The parent must list the child in its <code>CHILDREN</code> block, and the child must declare the <code>PARENT</code>:</p><div class="language-sql vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang">sql</span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Parent side</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Pipeline (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  CHILDREN {</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">    stages : LIST(Stage) </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">-&gt;</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;"> MIN</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(</span><span style="--shiki-light:#005CC5;--shiki-dark:#79B8FF;">1</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  }</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span>
<span class="line"></span>
<span class="line"><span style="--shiki-light:#6A737D;--shiki-dark:#6A737D;">-- Child side</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">DEFINE MACHINE Stage (</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  PARENT : Pipeline</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">  ...</span></span>
<span class="line"><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">)</span></span></code></pre></div><div class="warning custom-block"><p class="custom-block-title">WARNING</p><p>If you define a <code>PARENT</code> declaration pointing to a machine that does not have a matching <code>CHILDREN</code> entry, or vice versa, the engine will reject the definition.</p></div><div class="tip custom-block"><p class="custom-block-title">TIP</p><p>Child machines can themselves have children, forming multi-level hierarchies. A Pipeline can own Stages, and each Stage can own Jobs. CASCADE and SIGNAL PARENT TO work recursively through the full tree.</p></div>`,29)])])}const o=i(t,[["render",l]]);export{c as __pageData,o as default};
